import {createTransportStaff,poseTransportStaff,disposeTransportStaff} from '../residents/transport-staff.js';
export const HARBOR_GUIDE=Object.freeze({id:'harbor-seal',x:24.2,y:.05,z:12.45,yaw:Math.PI,radius:.70});
const target=Object.freeze({id:'resident.harbor-seal',type:'resident',residentId:'harbor-seal',at:{x:24.2,z:10.8},radius:.72,requiresClearApproach:true,label:'물범 안내원과 이야기하기',name:'물범 안내원',role:'마을 항구 안내',text:'나무 부두의 배를 타면 고요한 천문대 섬에 갈 수 있어요. 돌아오는 배도 같은 부두에 내려줘요. 등대 앞 의자에서는 잠시 앉아 바다를 바라봐요.'});
/** Nearby-only optional actor. The boat's readiness never depends on this load. */
export function createHarborStaff({root,load=()=>createTransportStaff('harbor-seal')}={}){
 let alive=true,generation=0,pending=null,model=null,wanted=false,failed=false,time=0,updates=0,lastDistance=Infinity,appeared=false,selected=true;
 const remove=()=>{if(model){disposeTransportStaff(model);model=null;appeared=false;}};
 function start(){const ticket=++generation;pending=Promise.resolve().then(()=>alive&&ticket===generation&&wanted?load():null).then(next=>{if(!next)return false;if(!alive||ticket!==generation||!wanted){disposeTransportStaff(next);return false;}model=next;model.position.set(HARBOR_GUIDE.x,HARBOR_GUIDE.y,HARBOR_GUIDE.z);model.rotation.y=HARBOR_GUIDE.yaw;appeared=lastDistance>=1.48;model.visible=appeared&&selected;root.add(model);poseTransportStaff(model);return true;}).catch(()=>{if(alive&&ticket===generation)failed=true;return false;}).finally(()=>{if(ticket===generation)pending=null;});}
 function reconcile(position,{selected:nextSelected=true}={}){if(!alive||!position)return Infinity;const reveal=!selected&&!!nextSelected;selected=!!nextSelected;const distance=Math.hypot(position.x-HARBOR_GUIDE.x,position.z-HARBOR_GUIDE.z);lastDistance=distance;if(reveal&&distance<1.48)appeared=false;if(distance>22){wanted=false;failed=false;if(pending){generation++;pending=null;}remove();return distance;}wanted=distance<=15||wanted;if(wanted&&!model&&!pending&&!failed)start();if(model){if(!appeared&&distance>=1.48)appeared=true;model.visible=appeared&&distance<=18&&selected;}return distance;}
 return{reconcile,update(dt,position,{paused=false,reducedMotion=false,selected=true}={}){const distance=reconcile(position,{selected});if(!model||!model.visible||distance>12||paused||!Number.isFinite(dt)||dt<=0||root.visible===false)return;time+=Math.min(dt,.05);poseTransportStaff(model,{mode:distance<2.8?'greeting':'idle',time,reducedMotion});updates++;},interactions:()=>model?.visible?[target]:[],circles:()=>model?.visible?[{id:target.id,x:HARBOR_GUIDE.x,z:HARBOR_GUIDE.z,radius:HARBOR_GUIDE.radius}]:[],whenSettled:()=>pending??Promise.resolve(!!model),snapshot:()=>({ready:!!model,visible:!!model?.visible,loading:!!pending,failed,updates,time,mode:model?.userData.mode??null}),dispose(){if(!alive)return;alive=false;wanted=false;generation++;pending=null;remove();}};
}
